    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    import sys
    def flood(s):
        seen=set([s]); st=[s]
        while st:
            y,x=st.pop()
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and g[ny][nx]==8 and (ny,nx) not in seen:
                    seen.add((ny,nx)); st.append((ny,nx))
        return seen
    for y in range(H):
