def f(g):
    g=[row[:] for row in g]
    h=len(g); w=len(g[0])
    # find connected components (4-conn) of each color; keep only pure solid rectangles -> recolor to 4
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                c=g[i][j]; stack=[(i,j)]; comp=[]
                seen[i][j]=True
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb] and g[na][nb]==c:
                            seen[na][nb]=True; stack.append((na,nb))
                rs=[r for r,_ in comp]; cs=[c2 for _,c2 in comp]
                rr,cc,minr,minc=min(rs),min(cs),max(rs),max(cs)
                if len(comp)==(rr-minr+1)*(cc-minc+1) and len(comp)>2:
                    for a,b in comp: g[a][b]=4
    return g
