def blocks(g,val):
    H,W=g.shape; seen=np.zeros_like(g,bool); out=[]
    for i in range(H):
        for j in range(W):
            if g[i,j]==val and not seen[i,j]:
                st=[(i,j)]; seen[i,j]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny,nx]==val and not seen[ny,nx]:
                            seen[ny,nx]=True; st.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                out.append((len(cells),(max(ys)-min(ys)+1,max(xs)-min(xs)+1),min(ys),min(xs))))
    return sorted(out,key=lambda x:-x[0])
